import unicodedata
import re
from urllib.parse import urlparse, urljoin, quote
import hmac
import hashlib
import time
import os

# Security configuration
SECRET_KEY = os.environ.get('REDIRECT_SECRET', '') or os.urandom(32)
ALLOWED_HOSTS = {'example.com', 'www.example.com', 'cdn.example.com', 'api.example.com'}
ALLOWED_SCHEMES = {'https'}
MAX_URL_LENGTH = 2048

def _compute_redirect_token(url, timestamp):
    """Generate HMAC token for redirect URL to prevent tampering."""
    msg = f"{url}|{timestamp}".encode('utf-8')
    return hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(), msg, hashlib.sha256).hexdigest()

def _validate_redirect_url(url):
    """Validate that a redirect URL is safe.

    Security checks:
    1. Length limit to prevent buffer issues
    2. Scheme must be HTTPS only
    3. Host must be in allowlist
    4. No embedded credentials
    5. No control characters
    """
    if not url or not isinstance(url, str):
        return None

    # Length check
    if len(url) > MAX_URL_LENGTH:
        return None

    # Block control characters (but allow valid Unicode)
    if any(unicodedata.category(c) == 'Cc' for c in url):
        return None

    # Parse the URL for validation
    parsed = urlparse(url)

    # Scheme validation
    if parsed.scheme.lower() not in ALLOWED_SCHEMES:
        return None

    # Host validation - extract hostname without port
    hostname = parsed.hostname
    if not hostname:
        return None

    # Normalize hostname for comparison
    hostname = hostname.lower().strip('.')

    if hostname not in ALLOWED_HOSTS:
        return None

    # Block embedded credentials
    if parsed.username or parsed.password:
        return None

    # Block fragments that could be used for DOM manipulation
    if parsed.fragment and '<' in parsed.fragment:
        return None

    return url

def prepare_redirect(user_url):
    """Prepare a validated redirect URL from user input.

    Applies Unicode normalization for consistent storage/comparison,
    then validates the URL against security policy.
    """
    if not user_url:
        return {'error': 'No URL provided'}

    # Normalize Unicode BEFORE validation to prevent normalization-based bypasses
    # NFKC is recommended for identifiers and URLs per RFC 3987
    normalized_url = unicodedata.normalize('NFKC', user_url)

    # Validate the normalized URL
    validated = _validate_redirect_url(normalized_url)
    if validated is None:
        return {'error': 'URL failed security validation'}

    # Re-validate after normalization to ensure consistency
    # (defense in depth - re-parse and check the final form)
    final_parsed = urlparse(validated)
    if final_parsed.hostname and final_parsed.hostname.lower().strip('.') not in ALLOWED_HOSTS:
        return {'error': 'URL failed post-normalization validation'}
    if final_parsed.scheme.lower() not in ALLOWED_SCHEMES:
        return {'error': 'URL failed scheme validation'}

    # Generate anti-tampering token
    timestamp = int(time.time())
    token = _compute_redirect_token(validated, timestamp)

    return {
        'redirect_url': validated,
        'token': token,
        'timestamp': timestamp
    }

def execute_redirect(redirect_data, provided_token):
    """Execute a redirect after verifying the token."""
    url = redirect_data.get('redirect_url', '')
    timestamp = redirect_data.get('timestamp', 0)

    # Ensure the provided token is a string to avoid TypeError from compare_digest
    if not isinstance(provided_token, str):
        return {'error': 'Invalid token'}

    # Verify freshness (5 minute window)
    if abs(time.time() - timestamp) > 300:
        return {'error': 'Redirect expired'}

    # Verify token
    expected_token = _compute_redirect_token(url, timestamp)
    if not hmac.compare_digest(provided_token, expected_token):
        return {'error': 'Invalid token'}

    return {'action': 'redirect', 'location': url}

def build_oauth_callback(base_url, state, code):
    """Build OAuth callback URL with validated base."""
    result = prepare_redirect(base_url)
    if 'error' in result:
        return result

    # Append OAuth parameters
    separator = '&' if '?' in result['redirect_url'] else '?'
    final_url = f"{result['redirect_url']}{separator}state={quote(state, safe='')}&code={quote(code, safe='')}"

    return {'callback_url': final_url, 'token': result['token'], 'timestamp': result['timestamp']}
